import React from "react";
import {type PiCardProps} from "@pihanga2/core";
import {useFormContext} from "@/cards/form/form.context";
import type {PiCheckboxEvents, PiCheckboxProps} from "./checkbox.types";

export const CheckboxComponent = (
  props: PiCardProps<PiCheckboxProps, PiCheckboxEvents>,
): React.ReactNode => {
  const {
    name,
    checked: propChecked = false,
    disabled,
    label,
    cardName,
    onChanged,
  } = props;

  // `id` and `invalid` may be injected by a parent pi/field card via
  // Pihanga's extra-prop forwarding.  They are not in the official type so
  // we read them through an escape hatch.
  const injectedId = (props as {id?: string}).id;
  const invalid = Boolean((props as {invalid?: boolean}).invalid);

  // Detect if we are inside a pi/form card via React context.
  const form = useFormContext();
  const useFormData = form.isInForm && Boolean(name);

  const checked = useFormData
    ? Boolean(form.formData[name!] ?? false)
    : propChecked;

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const newChecked = e.target.checked;
    if (useFormData) {
      form.handleChange(name!, newChecked);
    } else {
      onChanged({name, checked: newChecked});
    }
  }

  // Use the id injected by pi/field; fall back to a local id when standalone.
  const selfId = `${cardName}-${name ?? "checkbox"}`;
  const fieldId = injectedId ?? selfId;

  return (
    <div data-pihanga={cardName} className="flex items-center gap-2">
      <input
        id={fieldId}
        type="checkbox"
        checked={checked}
        onChange={handleChange}
        disabled={disabled}
        aria-invalid={invalid || undefined}
        className="h-4 w-4 rounded border-input accent-primary disabled:cursor-not-allowed disabled:opacity-50"
      />
      {label && (
        <label
          htmlFor={fieldId}
          className="text-sm leading-none cursor-pointer select-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
        >
          {label}
        </label>
      )}
    </div>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const PI_CHECKBOX_CARD = "pi/checkbox";

export const Checkbox = createCardDeclaration<
  PiCheckboxProps,
  PiCheckboxEvents
>(PI_CHECKBOX_CARD);

export const PI_CHECKBOX_ACTION = registerActions(PI_CHECKBOX_CARD, [
  "changed",
]);

export const onPiCheckboxChanged = createOnAction<PiCheckboxChangedEvent>(
  PI_CHECKBOX_ACTION.CHANGED,
);

export type PiCheckboxProps = {
  /**
   * Field name used to bind to FormContext when inside a pi/form card.
   * When provided the component reads its checked state from form data and
   * writes back via form.handleChange.
   */
  name?: string;

  /**
   * Controlled checked state used in standalone mode (outside a Form).
   * Ignored when `name` is set and the component is inside a pi/form.
   */
  checked?: boolean;

  /** When true, the checkbox is disabled and non-interactive. */
  disabled?: boolean;

  /**
   * Optional label text rendered next to the checkbox.
   * The label is automatically associated with the input via `htmlFor`.
   */
  label?: string;
};

export type PiCheckboxChangedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** New checked state after the change. */
  checked: boolean;
};

export type PiCheckboxEvents = {
  onChanged: PiCheckboxChangedEvent;
};

import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {CheckboxComponent} from "./checkbox.component";
import {PI_CHECKBOX_ACTION, PI_CHECKBOX_CARD} from "./checkbox.types";

export * from "./checkbox.types";

registerCardComponent({
  name: PI_CHECKBOX_CARD,
  component: CheckboxComponent,
  events: actionTypesToEvents(PI_CHECKBOX_ACTION),
});
